def is_valid_time_string(s):
    if not isinstance(s, str):
        return False
    parts = s.split(':')
    if len(parts) != 3:
        return False
    h, m, sec = parts
    if not (len(h) == 2 and len(m) == 2 and len(sec) == 2):
        return False
    if not (h.isdigit() and m.isdigit() and sec.isdigit()):
        return False
    hh, mm, ss = int(h), int(m), int(sec)
    return 0 <= hh <= 23 and 0 <= mm <= 59 and 0 <= ss <= 59

