def longest_constant_run_length(lst):
    if not lst:
        return 0
    best = cur = 1
    for i in range(1, len(lst)):
        if lst[i] == lst[i - 1]:
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 1
    return best

