import re
def is_snake_case(s):
    return bool(re.fullmatch(r'[a-z0-9]+(_[a-z0-9]+)*', s))

def shortest_words(words):
    min_len = len(words[0])
    for w in words:
        if len(w) < min_len:
            min_len = len(w)
    matches = [w for w in words if len(w) == min_len]
    matches.sort()
    return matches

